q:
Let $ABC$ be an equilateral triangle of side length $10$. A circle through $A$ is tangent to side $BC$, excluding its endpoints, at $X$, and meets sides $AB$ and $AC$ at points $D$ and $E$ other than $A$, respectively. If $BX>CX$ and $AD+AE=13$, find the length of segment $BX$.

Here $PQ$ denotes the length of segment $PQ$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
size(255);
pair B=(0,0),C=(10,0),A=(5,5*sqrt(3)),X=(7,0);
real radius=((A.x-X.x)^2+A.y^2)/(2*A.y);
pair O=(X.x,radius);
pair second(pair U) {
  pair v=U-A,w=A-O;
  real t=-2*(w.x*v.x+w.y*v.y)/(abs(v)^2);
  return A+t*v;
}
pair D=second(B),E=second(C);
draw(A--B--C--cycle);draw(circle(O,radius));
label("A",A,NW);label("B",B,SW);label("C",C,SE);
label("D",D,W);label("E",E,(1,0));label("X",X,S);
[/asy]
